# class-DX physics sandbox grammar
@dataclass(frozen=True)
class Quantity(Physical):  kind: str; value: float; unit: str; dimension: Dim
@dataclass(frozen=True)
class Body(Physical):      name: str; mass: Quantity; parts: tuple[Body, ...]
@dataclass(frozen=True)
class Cube(Body):          edge: Quantity; corners: tuple[float,float,float, ...]
@dataclass(frozen=True)
class Rod(Body):           length: Quantity; section: Quantity   # polymorphism: Rod is a Body
@dataclass(frozen=True)
class Joint(Physical):     at: tuple[float,float,float]; members: tuple[Body, ...]
# interaction is a Transformation with typed preconditions + proof footprint
class attach(Transformation[ tuple[Rod, Cube, Joint], Joint ]): ...
class joint_reaction(Transformation[ Joint, Quantity ]): ...
class KVL_like_equilibrium(Transformation[ tuple[Quantity, Quantity], Quantity ]): ...

# logistics grammar in class-DX (pythonic polymorphic)
@dataclass(frozen=True)
class Money:          amount: Decimal;  currency: str
@dataclass(frozen=True)
class Deadline:       date: date;       priority: int
@dataclass(frozen=True)
class Carrier(Physical):  domain: frozenset[str]; in_service: bool; hazmat_compat: bool; quote: Money
@dataclass(frozen=True)
class Warehouse:      region: str;      serves: frozenset[str]
@dataclass(frozen=True)
class Order(Physical):    origin: str;  destination: str; hazmat: bool; budget_cap: Money
# one rule, typed and precondition gated
class delivers_by(Transformation[ tuple[Carrier, Deadline], Satisfaction ]):
    def precondition(self, f):
        c, d = f
        if not c.in_service: return f"{c} not in_service"
        if c.quote.currency != "USD": return "quote not USD"
        return None   # may fire; else reason string recorded
# carries a proof footprint back to the Order/Carrier/Deadline facts
